#!/bin/bash -ex

main() {
  $(pwd)/gradlew -q javaToolchains

  # CB-34353 cache instrumentation: --console=plain (instead of --quiet) so Gradle
  # prints per-task outcome labels (FROM-CACHE / UP-TO-DATE / executed); tee to a
  # log and summarise below to read the build-cache hit rate on this runner. Keep
  # gradle's real exit code through the pipe (pipefail) so a test failure still fails.
  set -o pipefail
  local build_log
  build_log="$(mktemp)"
  $(pwd)/gradlew -Penv=jenkins -b build.gradle \
    test \
    jacocoTestReport \
    -x checkstyleMain \
    -x checkstyleTest \
    -x spotbugsMain \
    -x spotbugsTest \
    --no-daemon --console=plain --parallel -Dorg.gradle.jvmargs="-Xmx4096m -XX:MaxMetaspaceSize=256m -XX:+HeapDumpOnOutOfMemoryError" 2>&1 | tee "$build_log"

  echo "===== CB-34353 Gradle build-cache summary ====="
  echo "FROM-CACHE (all tasks) : $(grep -c 'FROM-CACHE' "$build_log" || true)"
  echo "UP-TO-DATE (all tasks) : $(grep -c 'UP-TO-DATE' "$build_log" || true)"
  echo ":test tasks FROM-CACHE : $(grep -cE '^> Task :.*:test FROM-CACHE$' "$build_log" || true)"
  echo ":test tasks executed   : $(grep -cE '^> Task :.*:test$' "$build_log" || true)"
  echo "==============================================="

  if [[ `git status --porcelain` ]]; then
    echo "There are local changes in git, which are autogenerated and not added in PR."
    echo ""
    echo "The following files were modified or generated during the build:"
    git status --porcelain
    exit 1
  fi
}

source $(pwd)/.github/actions/pull-request/prerequisites.sh
main "$@"
